<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {message} from 'ant-design-vue';import {api,type Picture,media} from '@/api/gallery';const route=useRoute(),pics=ref<Picture[]>([]),busy=ref(false),note=ref('');onMounted(async()=>{busy.value=true;try{const d=await api<{records:Picture[];searched:number;total:number}>('/picture/search/similar',{pictureId:route.params.id});pics.value=d.records;note.value=`比较 ${d.searched} 张图片（共 ${d.total} 张）`}catch(e){message.error((e as Error).message)}finally{busy.value=false}})</script><template><div class="page-heading"><span class="eyebrow">DISCOVER / SIMILARITY</span><h1>相似的灵感</h1><p>{{note}}</p></div><a-spin :spinning="busy"><div class="picture-grid"><article v-for="p in pics" :key="p.id" class="picture-card"><RouterLink :to="`/picture/${p.id}`"><img class="similar-image" :src="media(p,true)" :alt="p.name"/><h3>{{p.name}}</h3></RouterLink></article></div></a-spin></template>
